// Erzeugt von medikamente/scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"econazol":{"wirkmechanismus":"Hemmt das Wachstum von Pilzen, indem es den Aufbau ihrer Zellmembran stört. Econazol blockiert das pilzeigene Enzym Lanosterol-14-alpha-Demethylase und damit die Bildung von Ergosterol, dem wichtigsten Baustein der Pilzzellmembran; die Membran wird durchlässig und der Pilz stirbt ab. Es wirkt gegen Dermatophyten, Hefen und Schimmelpilze sowie gegen einige grampositive Bakterien. Nur ein kleiner Teil gelangt ins Blut; Econazol hemmt jedoch die Leberenzyme CYP3A4 und CYP2C9, was bei Blutverdünnern bedeutsam sein kann.","nebenwirkungen":{"haeufig":["Juckreiz und Brennen an der Anwendungsstelle (Haut bzw. Scheide und Schamlippen)","Schmerzen an der Anwendungsstelle"],"gelegentlich":["Rötung (Erythem)","Unwohlsein und Schwellung an der Anwendungsstelle"],"unbekannt":["Überempfindlichkeitsreaktionen, Angioödem (Schwellung)","Kontaktdermatitis, Ausschlag, Nesselsucht, Bläschen, Hautschuppung"]},"schwangerschaft":"Im 1. Drittel nur, wenn ärztlich als notwendig erachtet; danach nach ärztlicher Rücksprache möglich (geringe Aufnahme ins Blut).","stillzeit":"Mit Vorsicht anwenden – nicht bekannt, ob Econazol in die Muttermilch übergeht; nicht im Brustbereich auftragen.","hinweise":["Hautpilz: auch nach Abklingen der Beschwerden noch etwa 2 Wochen weiterbehandeln.","Bei gleichzeitiger Einnahme von Blutverdünnern (Phenprocoumon, Acenocoumarol) den INR kontrollieren lassen.","Latex-Kondome und Diaphragmen sind während der vaginalen Behandlung nicht sicher.","Pevisone enthält zusätzlich das Kortison Triamcinolon, ist rezeptpflichtig und nur kurzzeitig anzuwenden."],"darreichung":["Creme","Vaginalzäpfchen (Ovula)"]},"edoxaban":{"wirkmechanismus":"Hemmt die Blutgerinnung, indem es einen zentralen Gerinnungsfaktor direkt blockiert. Edoxaban bindet direkt, selektiv und reversibel an den Gerinnungsfaktor Xa, frei im Blut und im Gerinnsel. Dadurch wird weniger Thrombin gebildet und neue Gerinnsel entstehen nicht. Edoxaban wird kaum über CYP-Enzyme abgebaut, ist aber ein Substrat des Transporters P-Glykoprotein und wird zu etwa der Hälfte über die Nieren ausgeschieden.","nebenwirkungen":{"haeufig":["Anämie (Blutarmut)","Schwindel, Kopfschmerzen","Nasenbluten","Magen-Darm-Blutungen, Blutungen in Mund und Rachen","Bauchschmerzen, Übelkeit","Erhöhte Leberwerte (Bilirubin, GGT)","Haut- und Weichteilblutungen, Hautausschlag, Juckreiz","Blut im Urin, Scheidenblutungen, Blutungen an Einstichstellen"],"gelegentlich":["Hirnblutung","Thrombozytopenie (verminderte Blutplättchen)","Überempfindlichkeitsreaktionen, Nesselsucht","Blutungen am oder im Auge","Bluthusten","Erhöhte Transaminasen und alkalische Phosphatase","Blutungen an Operationswunden"],"selten":["Anaphylaktische Reaktion, allergisches Ödem","Subarachnoidal- und Subduralblutung","Blutung in den Herzbeutel","Blutungen im hinteren Bauchraum (retroperitoneal), Muskel- und Gelenkblutungen"],"unbekannt":["Antikoagulanzien-assoziierte Nephropathie (Nierenschädigung durch Blutungen in der Niere)"]},"schwangerschaft":"Kontraindiziert. Frauen im gebärfähigen Alter sollen während der Behandlung sicher verhüten.","stillzeit":"Kontraindiziert – entweder abstillen oder die Behandlung absetzen.","hinweise":["Einmal täglich, mit oder ohne Essen einnehmen; Tabletten dürfen zerstossen werden.","Nicht eigenmächtig absetzen – Gefahr von Schlaganfall oder Thrombose.","Nierenfunktion vor Beginn und regelmässig kontrollieren lassen; neue Medikamente in der Apotheke prüfen lassen.","Bei Blutungszeichen (schwarzer Stuhl, Blut im Urin, starke Kopfschmerzen, ungewöhnliche Blutergüsse) sofort ärztliche Hilfe holen."],"darreichung":["Filmtabletten"]},"eisen-ii-sulfat":{"wirkmechanismus":"Ersetzt fehlendes Eisen, das der Körper für die Bildung des roten Blutfarbstoffs braucht. Zweiwertiges Eisen (Fe2+) wird vor allem im Zwölffingerdarm über einen Transporter (DMT1) in die Darmzellen aufgenommen, dort zu dreiwertigem Eisen oxidiert und an Transferrin gebunden im Blut transportiert. Im Knochenmark wird es in das Hämoglobin der roten Blutkörperchen eingebaut, der Rest wird als Ferritin gespeichert. Die Retardform gibt das Eisen langsam ab, um den Magen weniger zu reizen.","nebenwirkungen":{"haeufig":["Verstopfung (Obstipation)","Durchfall","Bauchschmerzen, Blähbauch","Übelkeit","Dunkle bis schwarze Verfärbung des Stuhls (harmlos)"],"gelegentlich":["Erbrechen","Dyspepsie (Verdauungsbeschwerden)","Gastritis (Magenschleimhautentzündung)","Juckreiz, Hautausschlag","Kehlkopfschwellung (Larynxödem)"],"unbekannt":["Überempfindlichkeitsreaktionen, Nesselsucht","Zahnverfärbungen","Geschwüre im Mund oder in der Speiseröhre bei falscher Einnahme (Tablette gelutscht, zerkaut oder stecken geblieben)","Schleimhautschäden der Bronchien, wenn die Tablette in die Atemwege gelangt"]},"schwangerschaft":"Kann bei nachgewiesenem Eisenmangel angewendet werden; Eisen- und Folsäurebedarf sind in der Schwangerschaft erhöht.","stillzeit":"Kann angewendet werden; Eisen geht nur in geringer Menge in die Muttermilch über.","hinweise":["Tablette unzerkaut mit einem Glas Wasser schlucken, nicht lutschen; nicht im Liegen einnehmen.","Am besten nüchtern oder vor dem Essen einnehmen; Tee, Kaffee, Milch und Vollkornprodukte vermindern die Aufnahme. Bei Magenbeschwerden zum Essen einnehmen.","Schwarzer Stuhl ist harmlos. Für Kinder unerreichbar aufbewahren – Eisenvergiftung ist bei Kleinkindern lebensgefährlich.","Behandlungserfolg mit Blutbild und Ferritin kontrollieren; die Eisenspeicher füllen sich erst nach mehreren Monaten."],"darreichung":["Retardtabletten (Filmtabletten mit verzögerter Freisetzung)"]},"eisen-iii-carboxymaltose":{"wirkmechanismus":"Füllt die Eisenspeicher direkt über die Vene auf, unter Umgehung des Darms. Eisencarboxymaltose ist ein stabiler Komplex aus einem Eisen(III)-hydroxid-Kern und einer Kohlenhydrathülle, der kaum freies Eisen abgibt. Er wird von Fresszellen (Makrophagen) in Leber, Milz und Knochenmark aufgenommen; das freigesetzte Eisen wird an Transferrin gebunden oder als Ferritin gespeichert und für die Hämoglobinbildung genutzt. Dank der Stabilität können bis zu 1000 mg Eisen in einer Kurzinfusion gegeben werden.","nebenwirkungen":{"haeufig":["Hypophosphatämie (Phosphatmangel im Blut)","Kopfschmerzen","Schwindel","Flush (Hitzegefühl, Hautrötung)","Bluthochdruck","Übelkeit","Reaktionen an der Infusionsstelle (Schmerzen, Bluterguss, Verfärbung, Paravasat)"],"gelegentlich":["Überempfindlichkeitsreaktionen","Kribbeln (Parästhesien), Geschmacksstörung","Herzrasen, Blutdruckabfall","Atemnot","Erbrechen, Bauchschmerzen, Durchfall, Verstopfung","Juckreiz, Nesselsucht, Hautausschlag","Muskel-, Gelenk- und Rückenschmerzen","Fieber, Müdigkeit, Schüttelfrost, Wassereinlagerungen","Erhöhte Leberwerte"],"selten":["Anaphylaktische Reaktionen (allergischer Schock)","Bronchospasmus (Verkrampfung der Atemwege)","Kurze Bewusstlosigkeit (Synkope)","Venenentzündung","Angst"],"unbekannt":["Hypophosphatämische Osteomalazie (Knochenerweichung durch Phosphatmangel), Knochenbrüche","Kounis-Syndrom (allergisch ausgelöster Herzinfarkt)","Gesichtsschwellung (Angioödem)"]},"schwangerschaft":"Im 1. Drittel nicht anwenden. Im 2. und 3. Drittel nur, wenn der Nutzen das Risiko klar überwiegt; eine allergische Reaktion der Mutter kann beim Ungeborenen eine Verlangsamung des Herzschlags auslösen.","stillzeit":"Es geht nur sehr wenig Eisen in die Muttermilch über; die Anwendung ist nach ärztlicher Abwägung möglich.","hinweise":["Wird nur in Praxis oder Spital gegeben, wo eine allergische Reaktion sofort behandelt werden kann; nach der Infusion mindestens 30 Minuten beobachten.","Bei wiederholten Infusionen oder Knochenschmerzen und Muskelschwäche den Phosphatwert kontrollieren lassen.","Der Behandlungserfolg (Ferritin, Hämoglobin) wird frühestens nach etwa 4 Wochen kontrolliert.","Eisentabletten erst 5 Tage nach der letzten Infusion wieder einnehmen."],"darreichung":["Injektions- und Infusionslösung (Durchstechflaschen)"]},"eisen-iii-hydroxid-polymaltose-komplex":{"wirkmechanismus":"Ersetzt fehlendes Eisen für die Blutbildung. Das dreiwertige Eisen liegt als Eisen(III)-hydroxid-Kern vor, der von Polymaltose (einem Zuckerpolymer) umhüllt ist; dadurch wird im Darm kaum freies, reizendes Eisen frei. Die Aufnahme erfolgt über einen aktiven, vom Körper gesteuerten Mechanismus, sodass bei vollen Speichern weniger aufgenommen wird. Das Eisen wird an Transferrin gebunden, ins Hämoglobin eingebaut oder als Ferritin gespeichert. Nahrungsbestandteile beeinflussen die Aufnahme weniger stark als bei zweiwertigem Eisen.","nebenwirkungen":{"sehrHaeufig":["Dunkle Verfärbung des Stuhls (harmlos)"],"haeufig":["Durchfall","Übelkeit","Dyspepsie (Verdauungsbeschwerden)","Verstopfung (Obstipation)","Bauchschmerzen"],"gelegentlich":["Erbrechen","Gastritis (Magenschleimhautentzündung)","Zahnverfärbung (v. a. Tropfen und Sirup)","Kopfschmerzen","Juckreiz, Hautausschlag, Nesselsucht"],"unbekannt":["Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Im 2. und 3. Drittel ohne Hinweise auf Schäden für Mutter oder Kind untersucht und anwendbar; im 1. Drittel nur nach ärztlicher Abwägung.","stillzeit":"Kann angewendet werden; Eisen geht nur in geringer Menge in die Muttermilch über.","hinweise":["Während oder unmittelbar nach einer Mahlzeit einnehmen; Tropfen und Sirup können mit Fruchtsaft oder Brei gemischt werden.","Dunkler Stuhl ist harmlos und beeinflusst Tests auf verborgenes Blut im Stuhl nicht wesentlich.","Die Behandlung dauert meist mehrere Monate, bis die Eisenspeicher (Ferritin) aufgefüllt sind – Blutwerte kontrollieren lassen.","Für Kinder unerreichbar aufbewahren."],"darreichung":["Filmtabletten","Kautabletten","Tropfen","Sirup"]},"eisen-iii-saccharose":{"wirkmechanismus":"Füllt die Eisenspeicher direkt über die Vene auf, unter Umgehung des Darms. Eisensaccharose besteht aus einem Eisen(III)-hydroxid-Kern, der von Saccharose (Zucker) umhüllt ist. Der Komplex wird von Fresszellen (Makrophagen) in Leber, Milz und Knochenmark aufgenommen; das Eisen wird an Transferrin gebunden, ins Hämoglobin eingebaut oder als Ferritin gespeichert. Weil der Komplex weniger stabil ist als neuere Präparate, werden kleinere Einzeldosen in mehreren Sitzungen gegeben.","nebenwirkungen":{"haeufig":["Geschmacksstörung (Dysgeusie)","Blutdruckabfall oder Blutdruckanstieg","Übelkeit","Reaktionen an der Injektions- oder Infusionsstelle (Schmerzen, Brennen, Verfärbung)"],"gelegentlich":["Überempfindlichkeitsreaktionen","Kopfschmerzen, Schwindel, Kribbeln (Parästhesien)","Flush (Hitzegefühl), Venenentzündung","Atemnot","Erbrechen, Bauchschmerzen, Durchfall, Verstopfung","Juckreiz, Hautausschlag","Muskelkrämpfe, Muskel- und Gelenkschmerzen","Schüttelfrost, Müdigkeit, Wassereinlagerungen","Erhöhte Leberwerte, erhöhtes Ferritin"],"selten":["Kurze Bewusstlosigkeit (Synkope), Schläfrigkeit","Herzklopfen","Brustschmerzen","Verfärbung des Urins","Fieber, vermehrtes Schwitzen"],"unbekannt":["Anaphylaktische Reaktionen (allergischer Schock), Angioödem","Kreislaufkollaps","Bronchospasmus (Verkrampfung der Atemwege)","Verwirrtheit, Bewusstseinsstörung","Kounis-Syndrom (allergisch ausgelöster Herzinfarkt)","Langsamer oder schneller Herzschlag"]},"schwangerschaft":"Im 1. Drittel nicht anwenden. Im 2. und 3. Drittel nur, wenn der Nutzen das Risiko klar überwiegt; eine allergische Reaktion der Mutter kann das Ungeborene gefährden.","stillzeit":"Unverändertes Eisensaccharose geht kaum in die Muttermilch über; die Anwendung ist nach ärztlicher Abwägung möglich.","hinweise":["Wird nur in Praxis oder Spital gegeben, wo eine allergische Reaktion sofort behandelt werden kann; nach jeder Gabe mindestens 30 Minuten beobachten.","Der gesamte Eisenbedarf wird meist auf mehrere Termine verteilt.","Eisentabletten erst 5 Tage nach der letzten Gabe wieder einnehmen."],"darreichung":["Injektions- und Infusionslösung (Ampullen)"]},"empagliflozin":{"wirkmechanismus":"Senkt den Blutzucker, indem die Nieren überschüssigen Zucker mit dem Urin ausscheiden. Empagliflozin hemmt hochselektiv und reversibel den Natrium-Glukose-Cotransporter 2 (SGLT2) im proximalen Nierentubulus und vermindert so die Rückresorption von Glukose; pro Tag gehen etwa 60–80 g Zucker mit dem Urin verloren. Die Wirkung ist unabhängig vom Insulin und geht mit einer leichten osmotischen Diurese, vermehrter Natriumausscheidung und einer mässigen Senkung von Blutdruck und Gewicht einher. Die Schutzwirkung auf Herz und Nieren beruht vermutlich auf der Entlastung des Herzens und der Senkung des Drucks in den Nierenkörperchen (tubuloglomerulärer Feedback).","nebenwirkungen":{"sehrHaeufig":["Hypoglykämie (Unterzuckerung) bei Kombination mit Insulin oder Sulfonylharnstoffen"],"haeufig":["Genitalinfektionen wie Scheidenpilz (Vulvovaginitis) oder Eichelentzündung (Balanitis)","Harnwegsinfekte, einschliesslich Nierenbeckenentzündung","Vermehrtes Wasserlassen","Durst","Verstopfung","Juckreiz am ganzen Körper, Hautausschlag","Anstieg der Blutfette"],"gelegentlich":["Volumenmangel (Austrocknung, tiefer Blutdruck)","Nesselsucht (Urtikaria)","Angioödem (Schwellung von Gesicht, Lippen, Zunge)","Schmerzen beim Wasserlassen (Dysurie)","Anstieg von Kreatinin bzw. Abnahme der Nierenfunktion (eGFR), Anstieg des Hämatokrits"],"selten":["Diabetische Ketoazidose (lebensbedrohliche Übersäuerung, auch bei fast normalem Blutzucker)"],"sehrSelten":["Fournier-Gangrän (nekrotisierende Fasziitis im Genital- und Dammbereich)","Tubulointerstitielle Nephritis (Nierenentzündung)"]},"schwangerschaft":"Nicht anwenden: vorsichtshalber während der ganzen Schwangerschaft meiden (Nierenschäden im Tierversuch). Bei Eintritt einer Schwangerschaft ärztlich auf eine andere Behandlung umstellen.","stillzeit":"Nicht anwenden, da Empagliflozin im Tierversuch in die Milch übergeht und ein Risiko für das gestillte Kind nicht ausgeschlossen werden kann.","hinweise":["Der Urin-Zuckertest fällt unter der Behandlung immer positiv aus – zur Kontrolle den Blutzucker messen.","Bei akuten Erkrankungen mit Erbrechen, Durchfall oder wenig Trinken sowie vor grösseren Operationen nach ärztlicher Anweisung pausieren (Ketoazidose- und Austrocknungsgefahr).","Warnzeichen einer Ketoazidose (Übelkeit, Erbrechen, Bauchschmerzen, starker Durst, rasche Atmung, Verwirrtheit, ungewöhnliche Müdigkeit) sofort ärztlich abklären lassen.","Ausreichend trinken und auf Intimhygiene achten; Einnahme einmal täglich, unabhängig von den Mahlzeiten."],"darreichung":["Filmtabletten"]},"emtricitabin-tenofoviralafenamid":{"wirkmechanismus":"Hemmt die Vermehrung von HIV. Emtricitabin (ein Cytidin-Analogon) wird in den Zellen zum aktiven Triphosphat phosphoryliert; Tenofoviralafenamid ist eine im Blut stabile Vorstufe, die vor allem in Lymphozyten zu Tenofovir gespalten und zum aktiven Diphosphat umgewandelt wird. Beide werden von der Reversen Transkriptase in die Virus-DNA eingebaut und führen zum Kettenabbruch. Dank der tiefen Tenofovir-Spiegel im Blut werden Nieren und Knochen weniger belastet als mit Tenofovirdisoproxil; beide Wirkstoffe wirken auch gegen das Hepatitis-B-Virus.","nebenwirkungen":{"sehrHaeufig":["Übelkeit"],"haeufig":["Kopfschmerzen, Schwindel","Abnorme Träume","Durchfall, Erbrechen","Bauchschmerzen, Blähungen","Hautausschlag","Müdigkeit"],"gelegentlich":["Anämie","Dyspepsie (Verdauungsbeschwerden)","Angioödem (Schwellung von Haut und Schleimhäuten)","Juckreiz, Nesselsucht","Gelenkschmerzen"]},"schwangerschaft":"In der Schwangerschaft nach Abwägung durch die HIV-Fachperson anwendbar; die bisherigen Daten zeigen kein erhöhtes Fehlbildungsrisiko.","stillzeit":"HIV-positive Mütter sollen grundsätzlich nicht stillen (Übertragungsrisiko); ein Stillwunsch ist mit der HIV-Fachperson zu besprechen.","hinweise":["Einmal täglich mit oder ohne Mahlzeit einnehmen; keine Dosis auslassen.","Bei Hepatitis B nicht eigenmächtig absetzen.","Nierenfunktion regelmässig kontrollieren lassen."],"darreichung":["Filmtabletten"]},"emtricitabin-tenofovirdisoproxil":{"wirkmechanismus":"Hemmt die Vermehrung von HIV und verhindert bei vorbeugender Einnahme, dass sich das Virus nach einer Ansteckung im Körper festsetzt. Emtricitabin (ein Cytidin-Analogon) und Tenofovir (ein Adenosin-Nukleotid-Analogon, aus der Vorstufe Tenofovirdisoproxil freigesetzt) werden in den Zellen zu ihren aktiven Triphosphat- bzw. Diphosphat-Formen umgewandelt. Diese werden von der Reversen Transkriptase in die Virus-DNA eingebaut und führen zum Kettenabbruch. Beide Wirkstoffe wirken auch gegen das Hepatitis-B-Virus.","nebenwirkungen":{"sehrHaeufig":["Durchfall, Übelkeit, Erbrechen","Kopfschmerzen, Schwindel","Hautausschlag","Asthenie (Schwäche)","Hypophosphatämie (zu wenig Phosphat im Blut)","Erhöhte Kreatinkinase (CK)"],"haeufig":["Bauchschmerzen, Verdauungsbeschwerden, Blähungen","Schlaflosigkeit, abnorme Träume","Juckreiz, Nesselsucht, Hautverfärbung (vor allem an Handflächen und Fusssohlen)","Neutropenie (Mangel an weissen Blutkörperchen)","Allergische Reaktionen","Erhöhte Leber-, Bauchspeicheldrüsen-, Blutzucker- oder Triglyceridwerte","Müdigkeit, Schmerzen"],"gelegentlich":["Proximale Tubulopathie der Niere (inkl. Fanconi-Syndrom), Kreatininanstieg, Eiweiss im Urin","Anämie","Hypokaliämie (Kaliummangel)","Pankreatitis (Bauchspeicheldrüsenentzündung)","Angioödem (Schwellung von Haut und Schleimhäuten)","Rhabdomyolyse (Muskelzerfall), Muskelschwäche"],"selten":["Akutes Nierenversagen, Nierenentzündung, nephrogener Diabetes insipidus","Osteomalazie (Knochenerweichung) mit Knochenschmerzen und Brüchen","Laktatazidose (Übersäuerung des Blutes)","Fettleber, Hepatitis"]},"schwangerschaft":"Kann bei Bedarf in der Schwangerschaft angewendet werden; umfangreiche Daten zeigen kein erhöhtes Fehlbildungsrisiko.","stillzeit":"Beide Wirkstoffe gehen in die Muttermilch über; gemäss Fachinformation in der Stillzeit nicht anwenden. HIV-positive Mütter sollen grundsätzlich nicht stillen; bei PrEP das Vorgehen mit der Fachperson besprechen.","hinweise":["Mit einer Mahlzeit einnehmen.","PrEP: vor Beginn und danach alle 3 Monate HIV-Test sowie Kontrollen auf sexuell übertragbare Infektionen und der Nierenfunktion; PrEP schützt nicht vor anderen Geschlechtskrankheiten.","Regelmässig einnehmen – vergessene Dosen vermindern Wirkung bzw. Schutz.","Bei Hepatitis B nicht eigenmächtig absetzen."],"darreichung":["Filmtabletten"]},"enalapril":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Bildung des gefässverengenden Hormons Angiotensin II blockiert. Enalapril ist ein Prodrug, das in der Leber zu Enalaprilat aktiviert wird; dieses hemmt das Angiotensin-Konversionsenzym (ACE). Dadurch sinken Angiotensin II und Aldosteron: Die Gefässe weiten sich, die Niere scheidet mehr Salz und Wasser aus, und Herz und Gefässe werden langfristig entlastet. Weil ACE auch Bradykinin abbaut, steigt dessen Spiegel an – das erklärt Reizhusten und Angioödeme.","nebenwirkungen":{"sehrHaeufig":["Schwindel","Trockener Reizhusten","Übelkeit","Verschwommenes Sehen","Schwäche (Asthenie)"],"haeufig":["Kopfschmerzen, Depression","Hypotonie (tiefer Blutdruck), auch beim Aufstehen; Synkope (Ohnmacht)","Brustschmerzen, Herzrhythmusstörungen, Angina pectoris, beschleunigter Puls","Atemnot","Durchfall, Bauchschmerzen, Geschmacksveränderungen","Hautausschlag; Überempfindlichkeit mit Angioödem (Schwellung von Gesicht, Lippen, Zunge, Rachen)","Müdigkeit","Hyperkaliämie (erhöhtes Kalium), Kreatininanstieg"],"gelegentlich":["Anämie (Blutarmut)","Hypoglykämie (Unterzuckerung)","Verwirrtheit, Schläfrigkeit, Schlaflosigkeit, Kribbeln, Ohrensausen","Herzinfarkt oder Schlaganfall (infolge starken Blutdruckabfalls bei Risikopatienten)","Pankreatitis (Bauchspeicheldrüsenentzündung), Ileus, Magengeschwür, Erbrechen","Nierenfunktionsstörung, Nierenversagen, Eiweiss im Urin","Juckreiz, Nesselsucht, Haarausfall, vermehrtes Schwitzen, Erektionsstörungen","Hyponatriämie (Natriummangel), Muskelkrämpfe"],"selten":["Neutropenie, Agranulozytose, Thrombozytopenie, Knochenmarkdepression","Leberversagen, Hepatitis, cholestatische Gelbsucht","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme, Pemphigus","Raynaud-Syndrom, Lungeninfiltrate, eosinophile Pneumonie","Autoimmunerkrankungen, Lymphknotenschwellung","Entzündungen der Mundschleimhaut und Zunge"],"sehrSelten":["Intestinales Angioödem (Schwellung der Darmwand mit Bauchschmerzen)"],"unbekannt":["SIADH (Syndrom der inadäquaten ADH-Sekretion)"]},"schwangerschaft":"Im 1. Drittel nicht empfohlen; im 2. und 3. Drittel kontraindiziert, da fruchtschädigend (Nierenschäden, Fruchtwassermangel, verzögerte Schädelverknöcherung). Bei Kinderwunsch oder festgestellter Schwangerschaft rasch ärztlich auf ein anderes Mittel umstellen.","stillzeit":"Geht in sehr geringen Mengen in die Muttermilch über. In den ersten Wochen nach der Geburt und bei Frühgeborenen nicht empfohlen; bei älteren Säuglingen nach ärztlicher Abwägung möglich.","hinweise":["Bei Schwellung von Gesicht, Lippen, Zunge oder Rachen oder bei Atemnot sofort den Notruf wählen (Angioödem, auch nach langer Einnahme möglich).","Ein anhaltender trockener Reizhusten ist eine typische Nebenwirkung – ärztlich besprechen, nicht eigenmächtig absetzen.","Kalium und Nierenwerte regelmässig kontrollieren; kaliumhaltige Salzersatzmittel und Kaliumpräparate nur nach ärztlicher Rücksprache.","Bei starkem Durchfall, Erbrechen oder Flüssigkeitsmangel ärztlich klären, ob die Einnahme vorübergehend pausiert werden soll."],"darreichung":["Tabletten"]},"enoxaparin":{"wirkmechanismus":"Hemmt die Blutgerinnung und verhindert so, dass sich Blutgerinnsel bilden oder vergrössern. Enoxaparin ist ein niedermolekulares Heparin, das an den körpereigenen Hemmstoff Antithrombin bindet und dessen Wirkung vor allem gegen den Gerinnungsfaktor Xa, in geringerem Mass auch gegen Thrombin (Faktor IIa), stark verstärkt. Gegenüber unfraktioniertem Heparin ist die Wirkung besser vorhersehbar und hält länger an, sodass ein bis zwei Spritzen unter die Haut pro Tag genügen. Die Ausscheidung erfolgt überwiegend über die Nieren; die Wirkung kann über die Anti-Xa-Aktivität gemessen werden.","nebenwirkungen":{"sehrHaeufig":["Erhöhte Leberwerte (vor allem Transaminasen)"],"haeufig":["Blutungen, Blutarmut infolge Blutungen","Thrombozytopenie (verminderte Blutplättchen) oder Thrombozytose (vermehrte Blutplättchen)","Bluterguss, Schmerzen und andere Reaktionen an der Einstichstelle","Allergische Reaktionen","Kopfschmerzen","Nesselsucht, Juckreiz, Hautrötung"],"gelegentlich":["Hirnblutungen und Blutungen im hinteren Bauchraum (retroperitoneal)","Blasenbildende Hautentzündung","Hautreizung und Hautnekrose an der Einstichstelle","Leberzellschädigung"],"selten":["Anaphylaktische und anaphylaktoide Reaktionen bis Schock","Heparininduzierte Thrombozytopenie Typ II mit Thrombosen (Gefässverschlüsse bis Organinfarkt oder Gliedmassenischämie)","Spinale oder epidurale Hämatome nach rückenmarksnaher Anästhesie","Hyperkaliämie (erhöhtes Kalium)","Gallestauung (cholestatische Leberschädigung)","Haarausfall, Hautgefässentzündung","Osteoporose bei Langzeitanwendung über 3 Monate"]},"schwangerschaft":"Keine Hinweise auf Fruchtschädigung; Enoxaparin passiert die Plazenta im 2. Drittel nicht. Anwendung nur nach ärztlicher Abwägung; Schwangere mit künstlicher Herzklappe brauchen eine besonders enge Überwachung.","stillzeit":"Geht kaum in die Muttermilch über und wird vom Säugling über den Darm nicht aufgenommen; Anwendung in der Stillzeit möglich.","hinweise":["Unter die Haut spritzen (Bauch, abwechselnd links und rechts), nie in den Muskel; die Luftblase in der Fertigspritze nicht entfernen und die Einstichstelle nicht reiben.","Blutplättchen vor und während der Behandlung kontrollieren lassen (heparininduzierte Thrombozytopenie).","Vor Operationen, Zahnbehandlungen und Spinal- oder Periduralanästhesie die Behandlung angeben.","Bei Blutungszeichen (schwarzer Stuhl, Blut im Urin, starke Blutergüsse) oder neuen Thrombosezeichen sofort ärztlichen Rat holen."],"darreichung":["Injektionslösung in Fertigspritzen","Injektionslösung in Durchstechflaschen"]},"entecavir":{"wirkmechanismus":"Hemmt die Vermehrung des Hepatitis-B-Virus in der Leber. Entecavir ist ein Guanosin-Analogon, das in den Zellen zum aktiven Entecavir-Triphosphat phosphoryliert wird. Dieses konkurriert mit dem natürlichen Baustein Desoxyguanosintriphosphat und hemmt die virale Polymerase an drei Stellen: beim Start der DNA-Synthese (Priming), beim Umschreiben der prägenomischen RNA in DNA und bei der Synthese des zweiten DNA-Strangs. Gegen HIV wirkt es nur schwach, kann aber HIV-Resistenzen fördern.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Müdigkeit","Schwindel","Schlaflosigkeit","Übelkeit, Erbrechen, Durchfall","Dyspepsie (Verdauungsbeschwerden)","Erhöhte Leberwerte (Transaminasen)"],"gelegentlich":["Hautausschlag","Haarausfall"],"selten":["Anaphylaktoide Reaktion (schwere allergische Reaktion)"],"unbekannt":["Laktatazidose (Übersäuerung des Blutes), vor allem bei dekompensierter Lebererkrankung","Schwere Hepatitisschübe nach dem Absetzen"]},"schwangerschaft":"Nur anwenden, wenn unbedingt nötig (begrenzte Erfahrungen); Frauen im gebärfähigen Alter sollen wirksam verhüten.","stillzeit":"Gemäss Fachinformation nicht stillen (Übergang in die Muttermilch beim Menschen nicht bekannt).","hinweise":["Auf nüchternen Magen einnehmen: mindestens 2 Stunden nach und 2 Stunden vor einer Mahlzeit.","Nicht eigenmächtig absetzen – nach dem Absetzen Leberwerte regelmässig kontrollieren lassen.","Vor Beginn einen HIV-Test machen.","Die Behandlung schützt nicht vor einer Übertragung von Hepatitis B auf andere (z. B. beim Geschlechtsverkehr)."],"darreichung":["Filmtabletten"]},"eplerenon":{"wirkmechanismus":"Entlastet das Herz, indem es die schädlichen Wirkungen des Hormons Aldosteron blockiert. Eplerenon bindet selektiv an den Mineralokortikoid-Rezeptor und verhindert so, dass Aldosteron Salz- und Wasserrückhaltung, Kaliumverlust sowie Umbau- und Vernarbungsprozesse an Herz und Gefässen fördert. Im Gegensatz zu Spironolacton bindet es kaum an Androgen- und Progesteronrezeptoren, weshalb hormonelle Nebenwirkungen wie eine Brustvergrösserung selten sind. Eplerenon wird fast ausschliesslich über CYP3A4 abgebaut.","nebenwirkungen":{"haeufig":["Hyperkaliämie (erhöhtes Kalium), erhöhtes Cholesterin","Schwindel, Ohnmacht (Synkope), Kopfschmerzen, Schlaflosigkeit","Hypotonie (niedriger Blutdruck)","Verschlechterung der Herzinsuffizienz, Vorhofflimmern","Husten","Durchfall, Übelkeit, Erbrechen, Verstopfung","Hautausschlag, Juckreiz, Muskelkrämpfe, Rückenschmerzen","Eingeschränkte Nierenfunktion, Anstieg von Kreatinin und Harnstoff"],"gelegentlich":["Hyponatriämie (Natriummangel), Flüssigkeitsmangel, erhöhte Triglyceride","Eosinophilie (Vermehrung bestimmter weisser Blutkörperchen)","Schnellerer Puls, Blutdruckabfall beim Aufstehen, arterielle Thrombose in den Beinen","Gynäkomastie (Brustvergrösserung beim Mann)","Schilddrüsenunterfunktion","Gallenblasenentzündung","Nierenbeckenentzündung, Rachenentzündung","Vermehrtes Schwitzen, Unwohlsein"],"unbekannt":["Angioödem (Schwellung von Haut und Schleimhäuten)"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur nach sorgfältiger ärztlicher Abwägung anwenden.","stillzeit":"Nicht bekannt, ob Eplerenon in die Muttermilch übergeht; entweder abstillen oder die Behandlung absetzen.","hinweise":["Kalium vor Beginn, in der ersten Woche, nach einem Monat und danach regelmässig kontrollieren lassen.","Keine Kaliumpräparate, kaliumhaltigen Salzersatzmittel oder NSAR ohne ärztliche Rücksprache.","Vor jedem neuen Medikament, besonders Antibiotika und Pilzmitteln, auf Eplerenon hinweisen (CYP3A4-Wechselwirkungen)."],"darreichung":["Filmtabletten"]},"epoetin-alfa":{"wirkmechanismus":"Regt das Knochenmark an, mehr rote Blutkörperchen zu bilden. Epoetin alfa hat dieselbe Aminosäuresequenz wie das körpereigene Hormon Erythropoetin, das normalerweise vor allem in den Nieren gebildet wird. Es bindet an Erythropoetin-Rezeptoren auf Vorläuferzellen der roten Blutkörperchen im Knochenmark und fördert deren Vermehrung und Ausreifung. Nach einigen Tagen steigen die jungen roten Blutkörperchen (Retikulozyten), nach Wochen das Hämoglobin; dafür muss genügend Eisen vorhanden sein.","nebenwirkungen":{"sehrHaeufig":["Fieber","Übelkeit"],"haeufig":["Bluthochdruck","Venöse und arterielle Thrombosen (z. B. Shunt-Thrombose bei Dialyse)","Kopfschmerzen","Husten","Erbrechen, Durchfall","Gelenk-, Knochen- und Muskelschmerzen","Grippeähnliche Beschwerden, Schüttelfrost","Hautausschlag, Reaktionen an der Injektionsstelle, Wassereinlagerungen"],"gelegentlich":["Krampfanfälle","Hyperkaliämie (erhöhtes Kalium)","Nesselsucht","Überempfindlichkeitsreaktionen"],"selten":["Erythroblastopenie (PRCA) durch Antikörper gegen Erythropoetin, v. a. nach Spritzen unter die Haut bei Nierenkranken"],"unbekannt":["Hypertensive Krise mit Hirnfunktionsstörung (Enzephalopathie)","Herzinfarkt, Schlaganfall, Lungenembolie","Anaphylaxie, Angioödem (Schwellung von Gesicht und Rachen)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)"]},"schwangerschaft":"Nur nach strenger ärztlicher Nutzen-Risiko-Abwägung; die Erfahrungen sind begrenzt. Bei schwangeren Frauen nicht zur Eigenblutspende vor Operationen empfohlen.","stillzeit":"Nicht bekannt, ob Epoetin in die Muttermilch übergeht; Anwendung nur nach Abwägung.","hinweise":["Blutdruck regelmässig messen; bei starken Kopfschmerzen, Verwirrtheit oder Sehstörungen sofort ärztliche Hilfe holen.","Hämoglobin und Eisenwerte werden regelmässig kontrolliert; meist ist zusätzlich Eisen nötig.","Fertigspritzen im Kühlschrank (2–8 °C) lagern, nicht einfrieren oder schütteln.","Missbrauch als Dopingmittel ist verboten und gefährlich (Thrombosen, Herzinfarkt)."],"darreichung":["Injektionslösung in Fertigspritzen (Spritze unter die Haut oder in die Vene)"]},"ertapenem":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand verhindert. Ertapenem bindet an die Penicillin-bindenden Proteine (vor allem PBP 2 und 3) und hemmt die Quervernetzung des Zellwandbausteins Peptidoglykan. Es ist gegen die meisten Betalaktamasen einschliesslich ESBL stabil. Anders als andere Carbapeneme wirkt es kaum gegen Pseudomonas, Acinetobacter und Enterokokken; dank langer Halbwertszeit genügt eine Gabe pro Tag.","nebenwirkungen":{"haeufig":["Durchfall, Übelkeit, Erbrechen","Kopfschmerzen","Hautausschlag, Juckreiz","Venenentzündung oder Reizung an der Infusionsstelle","Erhöhte Leberwerte"],"gelegentlich":["Schwindel, Schläfrigkeit, Schlaflosigkeit, Verwirrtheit","Krampfanfälle","Blutdruckabfall, Atemnot","Pilzinfektionen im Mund (Soor), Verstopfung, Verdauungsbeschwerden","Clostridioides-difficile-assoziierter Durchfall","Nesselsucht, Hautrötung","Erhöhte Bilirubin- und Kreatininwerte"],"selten":["Neutropenie und Thrombozytopenie (Mangel an weissen Blutkörperchen bzw. Blutplättchen)","Allergische Reaktionen","Unruhe, Angst, Depression","Hypoglykämie (Unterzuckerung)"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Halluzinationen, Bewusstseinsveränderungen, Aggression, Delir","Muskelzuckungen (Myoklonien), Zittern, Gangstörung, Muskelschwäche","DRESS und akute generalisierte exanthematische Pustulose (schwere Hautreaktionen)","Zahnverfärbungen"]},"schwangerschaft":"Keine ausreichenden Erfahrungen bei Schwangeren. Anwendung nur, wenn der Nutzen das mögliche Risiko für das Kind klar überwiegt.","stillzeit":"Geht in die Muttermilch über. Nur nach ärztlicher Nutzen-Risiko-Abwägung anwenden.","hinweise":["Wird einmal täglich als Infusion gegeben (im Spital oder ambulant); Dosis bei schwacher Nierenfunktion angepasst.","Unbedingt angeben, wenn Valproinsäure eingenommen wird oder eine Antibiotika-Allergie besteht.","Bei starkem oder anhaltendem Durchfall – auch nach Behandlungsende – ärztliche Hilfe holen."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"erythromycin":{"wirkmechanismus":"Hemmt das Wachstum von Bakterien, indem es ihre Eiweissherstellung stoppt. Erythromycin bindet an die 50S-Untereinheit der bakteriellen Ribosomen und blockiert die Verlängerung der Eiweisskette; es wirkt vorwiegend bakteriostatisch, vor allem gegen grampositive Kokken und atypische Erreger. Zusätzlich regt es als Motilin-Agonist die Darmbewegungen an, was die häufigen Magen-Darm-Beschwerden erklärt. Erythromycin hemmt das Abbauenzym CYP3A4 und den Transporter P-Glykoprotein.","nebenwirkungen":{"haeufig":["Bauchschmerzen, Übelkeit, Erbrechen, Durchfall, Appetitlosigkeit (dosisabhängig)","Bei Anwendung auf der Haut: Brennen, Rötung, Trockenheit, Schuppung"],"gelegentlich":["Hautausschlag, Juckreiz, Nesselsucht"],"unbekannt":["QT-Verlängerung, Torsade de pointes und andere ventrikuläre Herzrhythmusstörungen","Cholestatische Hepatitis mit Gelbsucht, Leberfunktionsstörungen","Pseudomembranöse Kolitis (schwere Dickdarmentzündung)","Anaphylaxie (schwere allergische Reaktion)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme)","Reversibler Hörverlust, Tinnitus (vor allem bei hohen Dosen oder Niereninsuffizienz)","Pankreatitis (Bauchspeicheldrüsenentzündung)","Pylorusstenose (Magenpförtnerverengung) bei Säuglingen; Venenreizung bei Infusion"]},"schwangerschaft":"Langjährige Erfahrung, kein eindeutiges Fehlbildungsrisiko; einzelne Studien deuten auf ein leicht erhöhtes Risiko für Herzfehler bei Einnahme im 1. Drittel hin. Systemisch nur nach ärztlicher Abwägung; Anwendung auf der Haut gilt als unbedenklich.","stillzeit":"Geht in die Muttermilch über; beim Säugling sind Durchfall und selten eine Magenpförtnerverengung möglich. Systemisch nur nach ärztlicher Abwägung; Anwendung auf der Haut (nicht im Brustbereich) ist vertretbar.","hinweise":["Vor Beginn alle anderen Medikamente angeben: Erythromycin hat viele gefährliche Wechselwirkungen.","Bei Herzklopfen, Schwindel oder Ohnmacht sofort ärztliche Hilfe holen.","Akne-Lösung und -Salbe nicht auf Schleimhäute oder in die Augen bringen; die Hautanwendung hat praktisch keine Wechselwirkungen."],"darreichung":["Filmtabletten","Pulver zur Herstellung einer Infusionslösung","Lösung und Salbe zum Auftragen auf die Haut","Augensalbe (Kombination)"]},"esomeprazol":{"wirkmechanismus":"Senkt die Bildung von Magensäure stark und anhaltend. Esomeprazol ist das S-Enantiomer (eine der beiden Spiegelbildformen) von Omeprazol und wird langsamer abgebaut, wodurch höhere und gleichmässigere Spiegel erreicht werden. In den sauren Belegzellen der Magenschleimhaut wird es in die aktive Form umgewandelt und blockiert irreversibel die Protonenpumpe (H+/K+-ATPase), den letzten Schritt der Säurebildung. Esomeprazol wird über CYP2C19 und CYP3A4 abgebaut und hemmt selbst CYP2C19.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Bauchschmerzen, Blähungen","Durchfall oder Verstopfung","Übelkeit, Erbrechen","Gutartige Drüsenpolypen im Magen (Fundusdrüsenpolypen)"],"gelegentlich":["Wassereinlagerungen in den Beinen","Schlafstörungen","Schwindel, Kribbeln (Parästhesien), Schläfrigkeit","Mundtrockenheit","Erhöhte Leberwerte","Hautausschlag, Juckreiz, Nesselsucht","Knochenbrüche (Hüfte, Handgelenk, Wirbelsäule)"],"selten":["Leukopenie und Thrombozytopenie (Mangel an weissen Blutkörperchen bzw. Blutplättchen)","Überempfindlichkeitsreaktionen wie Fieber, Angioödem oder anaphylaktischer Schock","Hyponatriämie (Natriummangel)","Unruhe, Verwirrtheit, Depression","Geschmacksstörungen, verschwommenes Sehen","Bronchospasmus (Verkrampfung der Atemwege)","Hepatitis, Mundschleimhautentzündung, Pilzbefall im Magen-Darm-Trakt","Lichtempfindlichkeit, Haarausfall, Gelenk- und Muskelschmerzen"],"sehrSelten":["Agranulozytose, Panzytopenie (schwerer Mangel an Blutzellen)","Leberversagen, hepatische Enzephalopathie","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme","Halluzinationen, Aggressivität","Interstitielle Nephritis (Nierenentzündung)","Muskelschwäche, Gynäkomastie (Brustvergrösserung beim Mann)"],"unbekannt":["Hypomagnesiämie (Magnesiummangel), dadurch auch Calcium- und Kaliummangel","Mikroskopische Kolitis","Subakuter kutaner Lupus erythematodes"]},"schwangerschaft":"Kann nach ärztlicher Abwägung angewendet werden; Daten zu Esomeprazol und umfangreiche Erfahrungen mit Omeprazol zeigen kein erhöhtes Fehlbildungsrisiko.","stillzeit":"Es ist nicht bekannt, ob Esomeprazol in die Muttermilch übergeht; laut Fachinformation soll es in der Stillzeit nicht angewendet werden.","hinweise":["Tablette ganz mit Wasser schlucken, nicht kauen oder zerdrücken; bei Schluckbeschwerden darf sie in kohlensäurefreiem Wasser zerfallen gelassen werden.","Rezeptfreie Selbstbehandlung (20 mg) höchstens 14 Tage; ohne Besserung ärztlich abklären.","Nach längerer Einnahme nicht abrupt absetzen: vorübergehend vermehrte Säurebildung (Rebound) möglich.","Bei Langzeitbehandlung regelmässig die Notwendigkeit sowie Magnesium und Vitamin B12 überprüfen lassen."],"darreichung":["Magensaftresistente Tabletten","Magensaftresistentes Granulat zur Herstellung einer Suspension (Beutel)","Pulver zur Herstellung einer Injektions- oder Infusionslösung"]},"estradiol":{"wirkmechanismus":"Ersetzt das nach den Wechseljahren fehlende körpereigene Östrogen. Estradiol ist chemisch identisch mit dem natürlichen 17-beta-Estradiol und bindet an Östrogenrezeptoren in Gehirn, Knochen, Haut, Scheide und Gebärmutter. Dadurch werden Hitzewallungen gelindert, der Knochenabbau gebremst und die Scheidenschleimhaut wieder aufgebaut. Da Östrogen allein die Gebärmutterschleimhaut wuchern lässt, brauchen Frauen mit Gebärmutter zusätzlich ein Gestagen.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Bauchschmerzen, Übelkeit","Brustspannen, Brustschmerzen, Brustvergrösserung","Zwischen- oder Schmierblutungen","Wassereinlagerungen (Ödeme), Gewichtszunahme","Wadenkrämpfe","Hautreaktionen an der Auftragsstelle (Pflaster, Gel)","Scheidenpilz (vaginale Candidose)"],"gelegentlich":["Depressive Verstimmung, Nervosität","Schwindel, Sehstörungen","Migräne","Blähungen, Völlegefühl","Hautausschlag, Juckreiz"],"selten":["Venöse Thromboembolie (Beinvenenthrombose, Lungenembolie)","Gallenblasenerkrankungen","Überempfindlichkeitsreaktionen bis Anaphylaxie"],"unbekannt":["Brustkrebs (Risiko steigt mit der Dauer, vor allem bei Kombination mit Gestagen)","Gebärmutterschleimhautkrebs bei Östrogen-Monotherapie ohne Gestagenschutz","Eierstockkrebs (leicht erhöhtes Risiko)","Schlaganfall, koronare Herzkrankheit bei späterem Therapiebeginn","Chloasma (Pigmentflecken), Erythema nodosum oder multiforme","Wahrscheinliche Demenz bei Beginn nach dem 65. Lebensjahr"]},"schwangerschaft":"Kontraindiziert – nicht für die Anwendung in der Schwangerschaft bestimmt; tritt eine Schwangerschaft ein, sofort absetzen.","stillzeit":"Kontraindiziert – nicht für die Anwendung in der Stillzeit bestimmt.","hinweise":["Frauen mit Gebärmutter benötigen zusätzlich ein Gestagen; unerwartete oder anhaltende Blutungen ärztlich abklären.","So niedrig dosiert und so kurz wie nötig anwenden; mindestens jährlich ärztlich neu beurteilen lassen, Brustkrebs-Früherkennung wahrnehmen.","Gel und Pflaster: auf saubere, trockene, unverletzte Haut, nie auf die Brüste oder Schleimhäute; nach dem Auftragen des Gels Hände waschen und Hautkontakt mit Kindern vermeiden, bis es getrocknet ist.","Bei Beinschwellung, plötzlicher Atemnot, Brustschmerzen, Gelbsucht oder plötzlichen starken Kopfschmerzen sofort absetzen und ärztliche Hilfe holen."],"darreichung":["Tabletten","Transdermales Pflaster","Gel","Vaginaltabletten"]},"estriol":{"wirkmechanismus":"Ersetzt lokal das in den Wechseljahren fehlende Östrogen und baut so die dünn gewordene Scheidenhaut wieder auf. Estriol ist ein kurz wirksames natürliches Östrogen, das an die Östrogenrezeptoren der Scheiden- und Harnröhrenschleimhaut bindet. Es fördert die Vermehrung und Reifung der Epithelzellen, normalisiert den sauren pH-Wert und begünstigt die Ansiedlung von Milchsäurebakterien, was die Widerstandskraft gegen Infektionen erhöht. Wegen der kurzen Bindung am Rezeptor und der geringen Aufnahme ins Blut wird die Gebärmutterschleimhaut bei vaginaler Anwendung kaum stimuliert.","nebenwirkungen":{"unbekannt":["Lokale Reizung, Brennen oder Juckreiz in der Scheide","Brustspannen oder Brustschmerzen","Schmierblutungen nach den Wechseljahren","Vermehrter Ausfluss aus der Scheide","Übelkeit","Grippeähnliche Beschwerden","Wassereinlagerungen (Ödeme)"]},"schwangerschaft":"In der Schwangerschaft nicht angezeigt. Tritt unter der Behandlung eine Schwangerschaft ein, soll die Anwendung sofort beendet werden.","stillzeit":"In der Stillzeit nicht angezeigt: Estriol geht in die Muttermilch über und kann die Milchbildung vermindern.","hinweise":["Am besten abends vor dem Schlafengehen tief in die Scheide einführen.","Nach Abklingen der Beschwerden auf die niedrigste wirksame Erhaltungsdosis reduzieren; Nutzen und Risiken mindestens jährlich ärztlich überprüfen lassen.","Unerwartete Blutungen aus der Scheide, Knoten in der Brust oder Zeichen einer Thrombose (geschwollenes, schmerzendes Bein, plötzliche Atemnot) sofort ärztlich abklären lassen.","Regelmässige gynäkologische Kontrollen und Brustuntersuchungen wahrnehmen."],"darreichung":["Vaginalcreme","Vaginalzäpfchen (Ovula)","Vaginaltabletten (Kombination mit Milchsäurebakterien)"]},"ethinylestradiol-desogestrel":{"wirkmechanismus":"Verhindert eine Schwangerschaft vor allem, indem der Eisprung unterdrückt wird. Das Östrogen Ethinylestradiol und das Gestagen Desogestrel hemmen über die Hirnanhangdrüse die Ausschüttung von FSH und LH, sodass keine Eizelle heranreift. Desogestrel ist eine Vorstufe (Prodrug) und wird in Darmwand und Leber zum eigentlichen Wirkstoff Etonogestrel umgewandelt. Zusätzlich verdickt das Gestagen den Schleim am Gebärmutterhals und verändert die Gebärmutterschleimhaut; Ethinylestradiol stabilisiert den Zyklus.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Übelkeit, Bauchschmerzen","Depressive Verstimmung, Stimmungsschwankungen","Brustschmerzen, Brustspannen","Gewichtszunahme","Zwischen- und Schmierblutungen, vor allem in den ersten Monaten"],"gelegentlich":["Migräne","Erbrechen, Durchfall","Verminderte Libido","Wassereinlagerungen (Ödeme)","Hautausschlag, Nesselsucht","Brustvergrösserung"],"selten":["Venöse Thromboembolie (Beinvenenthrombose, Lungenembolie)","Arterielle Thromboembolie (Herzinfarkt, Schlaganfall)","Überempfindlichkeitsreaktionen","Erythema nodosum oder multiforme (entzündliche Hautknoten bzw. Hautausschlag)","Unverträglichkeit von Kontaktlinsen","Scheidenausfluss, Absonderung aus der Brust","Gesteigerte Libido, Gewichtsabnahme"],"unbekannt":["Blutdruckanstieg","Chloasma (bräunliche Pigmentflecken im Gesicht)","Lebertumoren","Auslösung oder Verschlechterung eines hereditären Angioödems","Leicht erhöhte Häufigkeit von Brustkrebsdiagnosen"]},"schwangerschaft":"Kontraindiziert; bei Eintritt einer Schwangerschaft sofort absetzen. Eine versehentliche Einnahme in der Frühschwangerschaft erhöht das Fehlbildungsrisiko nach heutigem Wissen nicht.","stillzeit":"Nicht empfohlen: Östrogene können die Milchmenge vermindern, und geringe Mengen gehen in die Muttermilch über. In der Stillzeit sind östrogenfreie Methoden besser geeignet.","hinweise":["Thromboserisiko: ohne Pille etwa 2, mit Desogestrel-Pillen etwa 9–12 von 10'000 Frauen pro Jahr (mit Levonorgestrel-Pillen 5–7); am höchsten im ersten Anwendungsjahr und nach einer Pause von 4 Wochen oder mehr.","Bei einseitiger Beinschwellung oder Wadenschmerzen, plötzlicher Atemnot, Brustschmerzen, Lähmungen, Seh- oder Sprachstörungen sofort ärztliche Hilfe holen.","Vergessene Tablette: bei weniger als 12 Stunden Verspätung sofort nachnehmen; bei mehr als 12 Stunden ist der Schutz vermindert – Anleitung der Packungsbeilage befolgen. Erbrechen oder starker Durchfall innerhalb von 3–4 Stunden gilt wie eine vergessene Tablette.","Schützt nicht vor HIV und anderen sexuell übertragbaren Infektionen."],"darreichung":["Tabletten (Einphasen- und Dreiphasenpräparate, Langzyklus)"]},"ethinylestradiol-drospirenon":{"wirkmechanismus":"Verhindert eine Schwangerschaft vor allem, indem der Eisprung unterdrückt wird. Das Östrogen Ethinylestradiol und das Gestagen Drospirenon hemmen über die Hirnanhangdrüse die Ausschüttung von FSH und LH, sodass keine Eizelle heranreift; zusätzlich verdickt sich der Schleim am Gebärmutterhals. Drospirenon ist mit Spironolacton verwandt: Es blockiert Mineralokortikoid-Rezeptoren (leicht entwässernd, kann Kalium erhöhen) und wirkt antiandrogen. Ethinylestradiol stabilisiert den Zyklus.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Migräne","Stimmungsschwankungen, depressive Verstimmung","Übelkeit","Brustschmerzen, Brustspannen","Zwischen- und Schmierblutungen, Ausbleiben der Abbruchblutung","Scheidenausfluss, Scheidenpilz (vaginale Candidose)"],"gelegentlich":["Depression, Nervosität, Schläfrigkeit, verminderte Libido","Schwindel, Kribbeln (Parästhesien)","Bluthochdruck, tiefer Blutdruck","Erbrechen, Durchfall, Bauchschmerzen, Blähungen","Akne, Juckreiz, Hautausschlag, Ekzem, Haarausfall","Wassereinlagerungen (Ödeme), Gewichtsveränderungen","Brustvergrösserung, Krampfadern"],"selten":["Venöse Thromboembolie (Beinvenenthrombose, Lungenembolie)","Arterielle Thromboembolie (Herzinfarkt, Schlaganfall)","Überempfindlichkeitsreaktionen, Asthma","Erythema nodosum oder multiforme (entzündliche Hautknoten bzw. Hautausschlag)","Hörminderung","Absonderung aus der Brust"],"unbekannt":["Chloasma (bräunliche Pigmentflecken im Gesicht)","Lebertumoren","Auslösung oder Verschlechterung eines hereditären Angioödems","Erhöhtes Kalium (Hyperkaliämie) bei eingeschränkter Nierenfunktion","Leicht erhöhte Häufigkeit von Brustkrebsdiagnosen"]},"schwangerschaft":"Kontraindiziert; bei Eintritt einer Schwangerschaft sofort absetzen. Eine versehentliche Einnahme in der Frühschwangerschaft erhöht das Fehlbildungsrisiko nach heutigem Wissen nicht.","stillzeit":"Nicht empfohlen: Östrogene können die Milchmenge vermindern, und geringe Mengen gehen in die Muttermilch über. In der Stillzeit sind östrogenfreie Methoden besser geeignet.","hinweise":["Thromboserisiko: ohne Pille etwa 2, mit Drospirenon-Pillen etwa 9–12 von 10'000 Frauen pro Jahr (mit Levonorgestrel-Pillen 5–7); am höchsten im ersten Anwendungsjahr und nach einer Pause von 4 Wochen oder mehr.","Bei einseitiger Beinschwellung oder Wadenschmerzen, plötzlicher Atemnot, Brustschmerzen, Lähmungen, Seh- oder Sprachstörungen sofort ärztliche Hilfe holen.","Vergessene Tablette sofort nachnehmen und die Anleitung der Packungsbeilage befolgen – wie lange eine Verspätung ohne Schutzverlust möglich ist, hängt vom Präparat ab. Erbrechen oder starker Durchfall innerhalb von 3–4 Stunden gilt wie eine vergessene Tablette.","Schützt nicht vor HIV und anderen sexuell übertragbaren Infektionen."],"darreichung":["Filmtabletten (21 + 7 bzw. 24 + 4 Tabletten)"]},"ethinylestradiol-etonogestrel":{"wirkmechanismus":"Verhindert eine Schwangerschaft vor allem, indem der Eisprung unterdrückt wird. Der Ring gibt über die Scheidenschleimhaut gleichmässig täglich etwa 120 Mikrogramm Etonogestrel und 15 Mikrogramm Ethinylestradiol ins Blut ab. Die beiden Hormone hemmen über die Hirnanhangdrüse die Ausschüttung von FSH und LH, sodass keine Eizelle heranreift; zusätzlich verdickt Etonogestrel, der aktive Metabolit von Desogestrel, den Schleim am Gebärmutterhals. Da die Hormone nicht über den Magen-Darm-Trakt aufgenommen werden, beeinträchtigen Erbrechen oder Durchfall die Wirkung nicht.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Migräne","Depression, verminderte Libido","Bauchschmerzen, Übelkeit","Akne","Brustspannen, Brustschmerzen","Juckreiz im Genitalbereich, Scheidenausfluss, Scheidenentzündung oder -infektion","Schmerzhafte Regelblutung, Unterleibsschmerzen","Gewichtszunahme","Fremdkörpergefühl, Herausgleiten des Rings, Beschwerden beim Geschlechtsverkehr"],"gelegentlich":["Stimmungsschwankungen","Schwindel, Gefühlsstörungen der Haut","Sehstörungen","Hitzewallungen, Blutdruckanstieg","Blähungen, Durchfall, Erbrechen, Verstopfung","Haarausfall, Ekzem, Hautausschlag","Rückenschmerzen, Muskelkrämpfe","Blasenentzündung, Harnwegsinfekt","Zwischenblutungen, Ausbleiben der Abbruchblutung","Müdigkeit, Reizbarkeit, Wassereinlagerungen"],"selten":["Venöse Thromboembolie (Beinvenenthrombose, Lungenembolie)","Arterielle Thromboembolie (Herzinfarkt, Schlaganfall)","Absonderung aus der Brust (Galaktorrhö)"],"unbekannt":["Überempfindlichkeitsreaktionen bis Angioödem, Nesselsucht","Chloasma (bräunliche Pigmentflecken im Gesicht)","Bruch des Rings mit möglicher Verletzung der Scheide","Gewebereaktionen der Scheide am Ring","Beschwerden am Penis des Partners","Auslösung oder Verschlechterung eines hereditären Angioödems"]},"schwangerschaft":"Kontraindiziert; bei Eintritt einer Schwangerschaft den Ring entfernen. Eine versehentliche Anwendung in der Frühschwangerschaft erhöht das Fehlbildungsrisiko nach heutigem Wissen nicht.","stillzeit":"Nicht empfohlen: Östrogene können die Milchmenge vermindern, und geringe Mengen gehen in die Muttermilch über. In der Stillzeit sind östrogenfreie Methoden besser geeignet.","hinweise":["Thromboserisiko: ohne hormonale Verhütung etwa 2, mit dem Etonogestrel-Ring etwa 6–12 von 10'000 Frauen pro Jahr (mit Levonorgestrel-Pillen 5–7); bei Beinschwellung, plötzlicher Atemnot, Brustschmerzen, Lähmungen oder Sehstörungen sofort ärztliche Hilfe holen.","War der Ring in Woche 1 oder 2 länger als 3 Stunden ausserhalb der Scheide, ist der Schutz vermindert: Ring sofort wieder einsetzen und 7 Tage zusätzlich ein Kondom verwenden (in Woche 3 Anleitung der Packungsbeilage befolgen).","Ring nach 3 Wochen am gleichen Wochentag entfernen, nach genau 7 Tagen Pause einen neuen Ring einsetzen; Ringe nicht wiederverwenden.","Schützt nicht vor HIV und anderen sexuell übertragbaren Infektionen."],"darreichung":["Vaginalring"]},"ethinylestradiol-gestoden":{"wirkmechanismus":"Verhindert eine Schwangerschaft vor allem, indem der Eisprung unterdrückt wird. Das Östrogen Ethinylestradiol und das Gestagen Gestoden hemmen über die Hirnanhangdrüse die Ausschüttung von FSH und LH, sodass keine Eizelle heranreift. Zusätzlich verdickt Gestoden den Schleim am Gebärmutterhals, der für Spermien schwer durchlässig wird, und verändert die Gebärmutterschleimhaut. Ethinylestradiol stabilisiert den Zyklus und sorgt für eine regelmässige Abbruchblutung in der einnahmefreien Zeit.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Übelkeit, Bauchschmerzen","Depressive Verstimmung, Stimmungsschwankungen","Brustschmerzen, Brustspannen","Gewichtszunahme","Zwischen- und Schmierblutungen, vor allem in den ersten Monaten"],"gelegentlich":["Migräne","Erbrechen, Durchfall","Verminderte Libido","Wassereinlagerungen (Ödeme)","Hautausschlag, Nesselsucht","Brustvergrösserung"],"selten":["Venöse Thromboembolie (Beinvenenthrombose, Lungenembolie)","Arterielle Thromboembolie (Herzinfarkt, Schlaganfall)","Überempfindlichkeitsreaktionen","Erythema nodosum oder multiforme (entzündliche Hautknoten bzw. Hautausschlag)","Unverträglichkeit von Kontaktlinsen","Scheidenausfluss, Absonderung aus der Brust","Gesteigerte Libido, Gewichtsabnahme"],"unbekannt":["Blutdruckanstieg","Chloasma (bräunliche Pigmentflecken im Gesicht)","Lebertumoren","Auslösung oder Verschlechterung eines hereditären Angioödems","Leicht erhöhte Häufigkeit von Brustkrebsdiagnosen"]},"schwangerschaft":"Kontraindiziert; bei Eintritt einer Schwangerschaft sofort absetzen. Eine versehentliche Einnahme in der Frühschwangerschaft erhöht das Fehlbildungsrisiko nach heutigem Wissen nicht.","stillzeit":"Nicht empfohlen: Östrogene können die Milchmenge vermindern, und geringe Mengen gehen in die Muttermilch über. In der Stillzeit sind östrogenfreie Methoden besser geeignet.","hinweise":["Thromboserisiko: ohne Pille etwa 2, mit Gestoden-Pillen etwa 9–12 von 10'000 Frauen pro Jahr (mit Levonorgestrel-Pillen 5–7); am höchsten im ersten Anwendungsjahr und nach einer Pause von 4 Wochen oder mehr.","Bei einseitiger Beinschwellung oder Wadenschmerzen, plötzlicher Atemnot, Brustschmerzen, Lähmungen, Seh- oder Sprachstörungen sofort ärztliche Hilfe holen.","Vergessene Tablette: bei weniger als 12 Stunden Verspätung sofort nachnehmen; bei mehr als 12 Stunden ist der Schutz vermindert – Anleitung der Packungsbeilage befolgen. Erbrechen oder starker Durchfall innerhalb von 3–4 Stunden gilt wie eine vergessene Tablette.","Schützt nicht vor HIV und anderen sexuell übertragbaren Infektionen."],"darreichung":["Tabletten (Einphasen- und Dreiphasenpräparate, Langzyklus)"]},"ethinylestradiol-levonorgestrel":{"wirkmechanismus":"Verhindert eine Schwangerschaft vor allem, indem der Eisprung unterdrückt wird. Das Östrogen Ethinylestradiol und das Gestagen Levonorgestrel hemmen über die Hirnanhangdrüse die Ausschüttung von FSH und LH, sodass keine Eizelle heranreift. Zusätzlich verdickt Levonorgestrel den Schleim am Gebärmutterhals, der für Spermien schwer durchlässig wird, und verändert die Gebärmutterschleimhaut. Ethinylestradiol stabilisiert den Zyklus und sorgt für eine regelmässige Abbruchblutung in der einnahmefreien Zeit.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Übelkeit, Bauchschmerzen","Depressive Verstimmung, Stimmungsschwankungen","Brustschmerzen, Brustspannen","Gewichtszunahme","Zwischen- und Schmierblutungen, vor allem in den ersten Monaten"],"gelegentlich":["Migräne","Erbrechen, Durchfall","Verminderte Libido","Wassereinlagerungen (Ödeme)","Hautausschlag, Nesselsucht","Brustvergrösserung"],"selten":["Venöse Thromboembolie (Beinvenenthrombose, Lungenembolie)","Arterielle Thromboembolie (Herzinfarkt, Schlaganfall)","Überempfindlichkeitsreaktionen","Erythema nodosum oder multiforme (entzündliche Hautknoten bzw. Hautausschlag)","Unverträglichkeit von Kontaktlinsen","Scheidenausfluss, Absonderung aus der Brust","Gesteigerte Libido, Gewichtsabnahme"],"unbekannt":["Blutdruckanstieg","Chloasma (bräunliche Pigmentflecken im Gesicht)","Lebertumoren","Auslösung oder Verschlechterung eines hereditären Angioödems","Leicht erhöhte Häufigkeit von Brustkrebsdiagnosen"]},"schwangerschaft":"Kontraindiziert; bei Eintritt einer Schwangerschaft sofort absetzen. Eine versehentliche Einnahme in der Frühschwangerschaft erhöht das Fehlbildungsrisiko nach heutigem Wissen nicht.","stillzeit":"Nicht empfohlen: Östrogene können die Milchmenge vermindern, und geringe Mengen gehen in die Muttermilch über. In der Stillzeit sind östrogenfreie Methoden besser geeignet.","hinweise":["Thromboserisiko: ohne Pille etwa 2, mit Levonorgestrel-Pillen etwa 5–7 von 10'000 Frauen pro Jahr; am höchsten im ersten Anwendungsjahr und nach einer Pause von 4 Wochen oder mehr.","Bei einseitiger Beinschwellung oder Wadenschmerzen, plötzlicher Atemnot, Brustschmerzen, Lähmungen, Seh- oder Sprachstörungen sofort ärztliche Hilfe holen.","Vergessene Tablette: bei weniger als 12 Stunden Verspätung sofort nachnehmen; bei mehr als 12 Stunden ist der Schutz vermindert – Anleitung der Packungsbeilage befolgen. Erbrechen oder starker Durchfall innerhalb von 3–4 Stunden gilt wie eine vergessene Tablette.","Schützt nicht vor HIV und anderen sexuell übertragbaren Infektionen."],"darreichung":["Tabletten (Einphasen- und Dreiphasenpräparate, Langzyklus)"]},"etonogestrel":{"wirkmechanismus":"Verhindert eine Schwangerschaft vor allem, indem der Eisprung unterdrückt wird. Das Stäbchen gibt gleichmässig das Gestagen Etonogestrel ab, den aktiven Metaboliten von Desogestrel. Etonogestrel bindet an Progesteronrezeptoren, hemmt über die Hirnanhangdrüse den Eisprung auslösenden LH-Anstieg und verdickt den Schleim am Gebärmutterhals, sodass Spermien kaum durchdringen. Die Freisetzung nimmt über die Zeit langsam ab.","nebenwirkungen":{"sehrHaeufig":["Unregelmässige Blutungen (seltener, häufiger, länger oder ausbleibend)","Kopfschmerzen","Akne","Brustspannen, Brustschmerzen","Gewichtszunahme","Scheideninfektion"],"haeufig":["Stimmungsschwankungen, depressive Verstimmung, Nervosität, verminderte Libido","Gesteigerter Appetit, Gewichtsabnahme","Schwindel, Hitzewallungen","Bauchschmerzen, Übelkeit, Blähungen","Haarausfall","Schmerzhafte Regelblutung, Eierstockzysten","Schmerzen oder Reaktionen an der Einlagestelle","Müdigkeit, grippeähnliche Beschwerden"],"gelegentlich":["Angst, Schlaflosigkeit, Schläfrigkeit, Migräne","Erbrechen, Verstopfung, Durchfall","Juckreiz, Hautausschlag, vermehrte Behaarung","Rücken-, Gelenk- und Muskelschmerzen","Blasenentzündung, Beschwerden beim Wasserlösen","Scheidenausfluss, Brustvergrösserung, Absonderung aus der Brust","Wassereinlagerungen (Ödeme), Fieber"],"unbekannt":["Überempfindlichkeitsreaktionen, Nesselsucht, Angioödem","Blutdruckanstieg","Chloasma (Pigmentflecken)","Wanderung des Implantats (selten bis in Blutgefässe oder Lunge), nicht tastbares Implantat","Nerven- oder Gefässverletzung beim Einlegen oder Entfernen","Blutgerinnsel (Thrombose, Embolie) in Einzelfällen"]},"schwangerschaft":"Kontraindiziert; bei Eintritt einer Schwangerschaft das Implantat entfernen. Eine versehentliche Exposition erhöht das Fehlbildungsrisiko nach bisherigen Daten nicht.","stillzeit":"Erlaubt: Milchmenge und -qualität werden nicht beeinträchtigt; geringe Mengen gehen in die Muttermilch über. Einlage in der Regel ab der 4. Woche nach der Geburt.","hinweise":["Das Stäbchen wird von einer geschulten Ärztin oder einem Arzt eingelegt und spätestens nach 3 Jahren entfernt bzw. ersetzt; es sollte unter der Haut tastbar sein.","Das Blutungsmuster ist nicht vorhersehbar und kann sich im Verlauf ändern.","Ist das Implantat nicht tastbar, bis zur Bestätigung der richtigen Lage zusätzlich verhüten.","Schützt nicht vor HIV und anderen sexuell übertragbaren Infektionen."],"darreichung":["Implantat (Hormonstäbchen zum Einlegen unter die Haut)"]},"evolocumab":{"wirkmechanismus":"Senkt das LDL-Cholesterin stark, indem es dafür sorgt, dass die Leber mehr «Cholesterin-Fänger» behält. Evolocumab ist ein humaner monoklonaler IgG2-Antikörper, der das im Blut zirkulierende Protein PCSK9 (Proproteinkonvertase Subtilisin/Kexin Typ 9) bindet. PCSK9 bewirkt normalerweise, dass LDL-Rezeptoren in der Leberzelle abgebaut werden; ist es blockiert, kehren mehr Rezeptoren an die Zelloberfläche zurück und entfernen LDL-Cholesterin aus dem Blut. Das LDL-Cholesterin sinkt dadurch um mehr als die Hälfte. Als Eiweiss wird Evolocumab wie körpereigene Antikörper abgebaut, nicht über Leberenzyme.","nebenwirkungen":{"haeufig":["Grippe (Influenza), Nasen-Rachen-Entzündung, Infekte der oberen Atemwege","Überempfindlichkeitsreaktionen, Hautausschlag","Übelkeit","Rückenschmerzen, Gelenkschmerzen, Muskelschmerzen","Reaktionen an der Injektionsstelle (z. B. Rötung, Schmerzen, Bluterguss)"],"gelegentlich":["Nesselsucht (Urtikaria)","Grippeähnliche Beschwerden"],"selten":["Angioödem (Schwellung von Gesicht, Lippen, Zunge oder Rachen)"]},"schwangerschaft":"Nicht anwenden, ausser der Zustand der Frau erfordert eine Behandlung – keine ausreichenden Erfahrungen; Antikörper gelangen vor allem im letzten Drittel zum Ungeborenen.","stillzeit":"Ein Risiko für den gestillten Säugling ist nicht auszuschliessen – ärztlich entscheiden, ob abgestillt oder auf die Behandlung verzichtet wird.","hinweise":["Im Kühlschrank (2–8 °C) lagern, nicht einfrieren; vor dem Spritzen etwa 30 Minuten Raumtemperatur annehmen lassen. Ausserhalb des Kühlschranks (bis 25 °C) höchstens 1 Monat haltbar.","Unter die Haut von Bauch, Oberschenkel oder Oberarm spritzen und die Stelle wechseln.","Keine bekannten Wechselwirkungen mit anderen Medikamenten; Statin und Ernährungsmassnahmen weiterführen."],"darreichung":["Injektionslösung im Fertigpen"]},"ezetimib":{"wirkmechanismus":"Senkt das Cholesterin, indem es dessen Aufnahme aus dem Darm bremst. Ezetimib hemmt das Transportprotein Niemann-Pick C1-Like 1 (NPC1L1) in der Dünndarmwand, über das Cholesterin aus Nahrung und Galle sowie Pflanzensterine aufgenommen werden. Dadurch gelangt weniger Cholesterin zur Leber; diese bildet mehr LDL-Rezeptoren und senkt so das LDL-Cholesterin im Blut. Zusammen mit einem Statin, das die Cholesterinbildung in der Leber hemmt, ergänzen sich die beiden Wirkprinzipien. Ezetimib wird zu einem ebenfalls wirksamen Glucuronid umgewandelt und nicht über CYP-Enzyme abgebaut.","nebenwirkungen":{"haeufig":["Bauchschmerzen, Durchfall, Blähungen","Müdigkeit","In Kombination mit einem Statin: Kopfschmerzen, Muskelschmerzen, erhöhte Transaminasen (Leberwerte)"],"gelegentlich":["Erhöhte Leberwerte (Gamma-GT, Transaminasen) und CK (Muskelenzym) unter Ezetimib allein","Husten","Verdauungsbeschwerden, Sodbrennen (Reflux), Übelkeit","Gelenkschmerzen, Muskelkrämpfe, Nackenschmerzen","Verminderter Appetit","Hitzewallungen, Bluthochdruck","Brustschmerzen, Schmerzen"],"unbekannt":["Überempfindlichkeitsreaktionen: Anaphylaxie, Angioödem, Ausschlag, Nesselsucht; Erythema multiforme","Thrombozytopenie (Mangel an Blutplättchen)","Myopathie, Rhabdomyolyse (Muskelzerfall)","Hepatitis, Gallensteine, Gallenblasenentzündung","Pankreatitis (Bauchspeicheldrüsenentzündung)","Schwindel, Kribbeln, Depression","Atemnot, Verstopfung, Schwäche"]},"schwangerschaft":"Allein nur bei eindeutiger Notwendigkeit (keine ausreichenden Daten); zusammen mit einem Statin kontraindiziert.","stillzeit":"Nicht anwenden – nicht bekannt, ob Ezetimib in die Muttermilch übergeht; zusammen mit einem Statin kontraindiziert.","hinweise":["Einmal täglich zu beliebiger Tageszeit, mit oder ohne Essen.","Bei Colestyramin oder Colesevelam Abstand einhalten: Ezetimib 2 Stunden vorher oder 4 Stunden nachher.","Cholesterinarme Ernährung und Bewegung fortsetzen; Blutfette und Leberwerte regelmässig kontrollieren.","Unerklärliche Muskelschmerzen oder -schwäche ärztlich melden."],"darreichung":["Tabletten"]}});
